using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.Linq;

/// <summary>
/// 障碍物网格编辑器 — 2D 俯视网格，点击格子放置/删除障碍物、敌人生成点、道具生成点。
/// 菜单: Tools > 障碍物网格编辑器
/// 保证位于格子正中心。每种障碍物独立记录预制体类型，切换类型不会覆盖已有障碍物。
/// 支持预案保存，配置持久化到 EditorPrefs。
/// </summary>
public class ObstacleGridEditor : EditorWindow
{
    const string PresetsPrefsKey = "ObstacleGridEditor_Presets";

    // === 编辑模式 ===
    enum EditMode { Obstacle, EnemySpawn, ItemSpawn }
    EditMode editMode = EditMode.Obstacle;

    // === 配置 ===
    GameObject roomPrefab;
    List<GameObject> obstaclePrefabs = new();
    int selectedObstacleIndex = 0;
    float cellSize = 24f;

    // === 偏移 ===
    Vector2 placementOffset = Vector2.zero;

    // === 运行时数据 ===
    Vector2 roomSize = new(20, 12);
    float cellOffsetX = 0.5f;
    float cellOffsetY = 0.5f;
    Dictionary<Vector2Int, int> obstacleCellMap = new();
    HashSet<Vector2Int> enemySpawnCells = new();
    HashSet<Vector2Int> itemSpawnCells = new();
    bool needsRefresh = true;
    Vector2Int? hoverCell;
    Vector2 scrollPos;

    // 障碍物类型颜色（循环使用，区分不同预制体）
    static readonly Color[] ObstacleColors =
    {
        new(0.2f, 0.8f, 0.2f, 0.7f),
        new(0.8f, 0.5f, 0.2f, 0.7f),
        new(0.2f, 0.7f, 0.7f, 0.7f),
        new(0.9f, 0.6f, 0.3f, 0.7f),
        new(0.6f, 0.2f, 0.6f, 0.7f),
        new(0.3f, 0.6f, 0.2f, 0.7f),
    };

    // === 预案系统 ===
    [System.Serializable]
    class ConfigData
    {
        public string roomPrefabGUID;
        public List<string> obstaclePrefabGUIDs = new();
        public int selectedObstacleIndex;
        public float cellSize = 24f;
    }

    [System.Serializable]
    class PresetData
    {
        public string name;
        public ConfigData config;
    }

    [System.Serializable]
    class PresetList
    {
        public List<PresetData> presets = new();
        public string currentName = "";
    }

    PresetList _presets;
    string _newPresetName = "";
    bool _renaming;
    string _renameBuffer = "";

    [MenuItem("Tools/障碍物网格编辑器")]
    static void ShowWindow() => GetWindow<ObstacleGridEditor>("障碍物网格编辑器");

    void OnEnable()
    {
        LoadPresets();
    }

    void OnDestroy()
    {
        SaveCurrentToPresets();
        SavePresetsToDisk();
    }

    // ──────────────────────────────────────────────
    //  GUID 工具
    // ──────────────────────────────────────────────

    static string ToGUID(Object obj)
    {
        if (obj == null) return "";
        var path = AssetDatabase.GetAssetPath(obj);
        if (string.IsNullOrEmpty(path)) return "";
        return AssetDatabase.AssetPathToGUID(path);
    }

    static T FromGUID<T>(string guid) where T : Object
    {
        if (string.IsNullOrEmpty(guid)) return null;
        var path = AssetDatabase.GUIDToAssetPath(guid);
        if (string.IsNullOrEmpty(path)) return null;
        return AssetDatabase.LoadAssetAtPath<T>(path);
    }

    static List<string> ToGUIDList(List<GameObject> objs)
    {
        var result = new List<string>();
        foreach (var o in objs)
            result.Add(o == null ? "" : ToGUID(o));
        return result;
    }

    static List<GameObject> FromGUIDList(List<string> guids)
    {
        var result = new List<GameObject>();
        if (guids == null) return result;
        foreach (var g in guids)
            result.Add(FromGUID<GameObject>(g));
        return result;
    }

    // ──────────────────────────────────────────────
    //  预案存取
    // ──────────────────────────────────────────────

    void LoadPresets()
    {
        var json = EditorPrefs.GetString(PresetsPrefsKey, "");
        if (!string.IsNullOrEmpty(json))
            _presets = JsonUtility.FromJson<PresetList>(json);

        if (_presets == null || _presets.presets.Count == 0)
        {
            _presets = new PresetList();
            _presets.presets.Add(new PresetData { name = "默认", config = new ConfigData() });
            _presets.currentName = "默认";
        }

        ApplyConfigToFields(GetCurrentPreset()?.config);
    }

    PresetData GetCurrentPreset()
    {
        if (_presets == null || _presets.presets.Count == 0) return null;
        return _presets.presets.FirstOrDefault(p => p.name == _presets.currentName)
               ?? _presets.presets[0];
    }

    void SaveCurrentToPresets()
    {
        var p = GetCurrentPreset();
        if (p != null) p.config = CollectFieldsToConfig();
    }

    void SavePresetsToDisk()
    {
        EditorPrefs.SetString(PresetsPrefsKey, JsonUtility.ToJson(_presets));
    }

    void ApplyConfigToFields(ConfigData d)
    {
        if (d == null) return;
        roomPrefab = FromGUID<GameObject>(d.roomPrefabGUID);
        obstaclePrefabs = FromGUIDList(d.obstaclePrefabGUIDs);
        selectedObstacleIndex = d.selectedObstacleIndex;
        cellSize = d.cellSize;
        needsRefresh = true;
    }

    ConfigData CollectFieldsToConfig()
    {
        return new ConfigData
        {
            roomPrefabGUID = ToGUID(roomPrefab),
            obstaclePrefabGUIDs = ToGUIDList(obstaclePrefabs),
            selectedObstacleIndex = selectedObstacleIndex,
            cellSize = cellSize
        };
    }

    // ──────────────────────────────────────────────
    //  数据刷新
    // ──────────────────────────────────────────────

    void RefreshData()
    {
        obstacleCellMap.Clear();
        enemySpawnCells.Clear();
        itemSpawnCells.Clear();

        if (roomPrefab == null) { needsRefresh = false; return; }

        var root = PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(roomPrefab));

        var roomRoot = root.GetComponent<RoomRoot>();
        if (roomRoot != null)
            roomSize = roomRoot.roomSize;

        cellOffsetX = (Mathf.RoundToInt(roomSize.x) % 2 == 0) ? 0.5f : 0f;
        cellOffsetY = (Mathf.RoundToInt(roomSize.y) % 2 == 0) ? 0.5f : 0f;

        var container = root.transform.Find("Obstacles");
        if (container != null)
        {
            for (int i = 0; i < container.childCount; i++)
            {
                var child = container.GetChild(i);
                var cell = WorldToCell(child.localPosition);
                obstacleCellMap[cell] = -1;
            }
        }

        if (roomRoot != null)
        {
            if (roomRoot.enemySpawnPoints != null)
                foreach (var t in roomRoot.enemySpawnPoints)
                    if (t) enemySpawnCells.Add(WorldToCell(t.localPosition));
            if (roomRoot.itemSpawnPoints != null)
                foreach (var t in roomRoot.itemSpawnPoints)
                    if (t) itemSpawnCells.Add(WorldToCell(t.localPosition));
        }

        PrefabUtility.UnloadPrefabContents(root);
        needsRefresh = false;
    }

    Vector2Int WorldToCell(Vector3 worldPos)
    {
        return new Vector2Int(
            Mathf.RoundToInt(worldPos.x - cellOffsetX),
            Mathf.RoundToInt(worldPos.y - cellOffsetY));
    }

    Vector3 CellToWorld(Vector2Int cell)
    {
        return new Vector3(cell.x + cellOffsetX + placementOffset.x, cell.y + cellOffsetY + placementOffset.y, 0);
    }

    /// <summary>不带偏移的格子→世界坐标（用于预制体原有障碍物）</summary>
    Vector3 CellToWorldNoOffset(Vector2Int cell)
    {
        return new Vector3(cell.x + cellOffsetX, cell.y + cellOffsetY, 0);
    }

    // ──────────────────────────────────────────────
    //  UI
    // ──────────────────────────────────────────────

    void OnGUI()
    {
        if (needsRefresh) RefreshData();

        _scroll = EditorGUILayout.BeginScrollView(_scroll);

        GUILayout.Label("障碍物网格编辑器", EditorStyles.boldLabel);
        EditorGUILayout.HelpBox(
            "选择房间预制体 → 在网格上放置障碍物/生成点 → 保存。\n" +
            "配置自动保存，关闭 Unity 不丢失。", MessageType.Info);

        DrawPresetSection();

        // ── 配置区 ──
        EditorGUILayout.Space(5);
        GUILayout.Label("配置", EditorStyles.boldLabel);

        EditorGUI.BeginChangeCheck();
        roomPrefab = (GameObject)EditorGUILayout.ObjectField("房间预制体", roomPrefab, typeof(GameObject), false);
        if (EditorGUI.EndChangeCheck())
        {
            needsRefresh = true;
            SaveCurrentToPresets();
            SavePresetsToDisk();
        }

        EditorGUILayout.LabelField("障碍物预制体:");
        for (int i = obstaclePrefabs.Count - 1; i >= 0; i--)
        {
            EditorGUILayout.BeginHorizontal();
            GUI.color = ObstacleColors[i % ObstacleColors.Length];
            GUILayout.Label($"[{i}]", GUILayout.Width(25));
            GUI.color = Color.white;

            obstaclePrefabs[i] = (GameObject)EditorGUILayout.ObjectField(obstaclePrefabs[i], typeof(GameObject), false);
            if (GUILayout.Button("删", GUILayout.Width(30)))
            {
                obstaclePrefabs.RemoveAt(i);
                var toRemove = obstacleCellMap.Where(kv => kv.Value == i).Select(kv => kv.Key).ToList();
                foreach (var c in toRemove) obstacleCellMap.Remove(c);
                var toFix = obstacleCellMap.Where(kv => kv.Value > i).ToList();
                foreach (var kv in toFix) obstacleCellMap[kv.Key] = kv.Value - 1;

                if (selectedObstacleIndex >= obstaclePrefabs.Count)
                    selectedObstacleIndex = Mathf.Max(0, obstaclePrefabs.Count - 1);

                SaveCurrentToPresets();
                SavePresetsToDisk();
            }
            EditorGUILayout.EndHorizontal();
        }
        if (GUILayout.Button("+ 添加障碍物预制体"))
        {
            obstaclePrefabs.Add(null);
            SaveCurrentToPresets();
            SavePresetsToDisk();
        }

        if (obstaclePrefabs.Count > 0 && obstaclePrefabs.All(p => p != null))
        {
            string[] names = obstaclePrefabs.Select((p, i) => $"[{i}] {p.name}").ToArray();
            selectedObstacleIndex = EditorGUILayout.Popup("当前障碍物", selectedObstacleIndex, names);
        }

        cellSize = EditorGUILayout.Slider("格子像素大小", cellSize, 12f, 40f);
        placementOffset = EditorGUILayout.Vector2Field("放置偏移 (x,y)", placementOffset);

        EditorGUILayout.Space(10);

        bool canDrawGrid = roomPrefab != null;

        if (roomPrefab == null)
            EditorGUILayout.HelpBox("请选择房间预制体", MessageType.Info);

        // ── 编辑模式 ──
        EditorGUILayout.Space(3);
        GUILayout.Label("编辑模式", EditorStyles.miniBoldLabel);
        editMode = (EditMode)EditorGUILayout.EnumPopup("当前模式", editMode);

        bool obstacleMissing = obstaclePrefabs.Count == 0 || obstaclePrefabs.Any(p => p == null);

        switch (editMode)
        {
            case EditMode.Obstacle:
                if (obstacleMissing)
                    EditorGUILayout.HelpBox("请添加障碍物预制体", MessageType.Info);
                else
                    EditorGUILayout.HelpBox(
                        "点击空格放置当前选中类型的障碍物\n" +
                        "点击已有障碍物 → 替换为当前类型\n" +
                        "再次点击同类型障碍物 → 删除", MessageType.None);
                canDrawGrid = canDrawGrid && !obstacleMissing;
                break;
            case EditMode.EnemySpawn:
                EditorGUILayout.HelpBox("点击格子放置/删除敌人生成点", MessageType.None);
                break;
            case EditMode.ItemSpawn:
                EditorGUILayout.HelpBox("点击格子放置/删除道具生成点", MessageType.None);
                break;
        }

        if (canDrawGrid)
        {
            EditorGUILayout.Space(5);
            EditorGUILayout.BeginHorizontal();
            DrawLegend(new Color(0.6f, 0.6f, 0.6f, 0.5f), "空格");
            DrawLegend(ObstacleColors[selectedObstacleIndex % ObstacleColors.Length], "障碍物");
            DrawLegend(new Color(0.2f, 0.5f, 0.9f, 0.7f), "敌人点");
            DrawLegend(new Color(0.7f, 0.3f, 0.9f, 0.7f), "道具点");
            EditorGUILayout.EndHorizontal();

            EditorGUILayout.Space(5);
            DrawGrid();

            EditorGUILayout.Space(10);
            EditorGUILayout.BeginHorizontal();
            if (GUILayout.Button("保存到预制体", GUILayout.Height(25)))
                EditorApplication.delayCall += () => SaveToPrefab();
            if (GUILayout.Button("刷新", GUILayout.Width(60)))
                needsRefresh = true;
            if (GUILayout.Button("清空当前模式", GUILayout.Width(100)))
            {
                ClearCurrentMode();
                Repaint();
            }
            EditorGUILayout.EndHorizontal();
        }

        EditorGUILayout.LabelField(
            $"房间尺寸: {roomSize.x}×{roomSize.y} | " +
            $"障碍物: {obstacleCellMap.Count} | " +
            $"敌人点: {enemySpawnCells.Count} | " +
            $"道具点: {itemSpawnCells.Count}");
        {
            string info = hoverCell.HasValue
                ? $"当前格子: ({hoverCell.Value.x}, {hoverCell.Value.y})" +
                  (obstacleCellMap.TryGetValue(hoverCell.Value, out int idx) ? $" | 障碍物[{idx}]" : "")
                : "";
            EditorGUILayout.LabelField(info, EditorStyles.miniLabel);
        }

        EditorGUILayout.EndScrollView();

        if (GUI.changed)
        {
            SaveCurrentToPresets();
            SavePresetsToDisk();
        }
    }

    Vector2 _scroll;

    void DrawPresetSection()
    {
        EditorGUILayout.Space();
        GUILayout.Label("预案", EditorStyles.miniBoldLabel);

        if (_renaming)
        {
            EditorGUILayout.BeginHorizontal();
            _renameBuffer = EditorGUILayout.TextField("编辑预案名", _renameBuffer);
            if (GUILayout.Button("确定", GUILayout.Width(40)))
            {
                var p = GetCurrentPreset();
                if (p != null && !string.IsNullOrWhiteSpace(_renameBuffer))
                {
                    _presets.currentName = _renameBuffer;
                    p.name = _renameBuffer;
                    SavePresetsToDisk();
                }
                _renaming = false;
            }
            if (GUILayout.Button("取消", GUILayout.Width(40)))
                _renaming = false;
            EditorGUILayout.EndHorizontal();
        }

        string[] names = _presets.presets.Select(p => p.name).ToArray();
        int curIdx = System.Array.IndexOf(names, _presets.currentName);
        if (curIdx < 0) curIdx = 0;

        EditorGUILayout.BeginHorizontal();
        int newIdx = EditorGUILayout.Popup("当前预案", curIdx, names);
        if (newIdx != curIdx)
        {
            SaveCurrentToPresets();
            _presets.currentName = names[newIdx];
            ApplyConfigToFields(GetCurrentPreset()?.config);
            SavePresetsToDisk();
        }

        if (GUILayout.Button("重命名", GUILayout.Width(60)))
        {
            var p = GetCurrentPreset();
            if (p != null)
            {
                _renameBuffer = p.name;
                _renaming = true;
            }
        }

        if (GUILayout.Button("删除", GUILayout.Width(50)))
        {
            if (_presets.presets.Count <= 1)
                Warn("至少保留一个预案");
            else
            {
                var p = GetCurrentPreset();
                if (p != null)
                {
                    _presets.presets.Remove(p);
                    _presets.currentName = _presets.presets[0].name;
                    ApplyConfigToFields(GetCurrentPreset()?.config);
                    SavePresetsToDisk();
                }
            }
        }
        EditorGUILayout.EndHorizontal();

        EditorGUILayout.BeginHorizontal();
        _newPresetName = EditorGUILayout.TextField("新预案名称", _newPresetName);
        if (GUILayout.Button("新建", GUILayout.Width(50)))
        {
            if (string.IsNullOrWhiteSpace(_newPresetName))
                Warn("请输入预案名称");
            else if (_presets.presets.Any(p => p.name == _newPresetName))
                Warn("预案名称已存在");
            else
            {
                SaveCurrentToPresets();
                _presets.presets.Add(new PresetData
                {
                    name = _newPresetName,
                    config = CollectFieldsToConfig()
                });
                _presets.currentName = _newPresetName;
                _newPresetName = "";
                SavePresetsToDisk();
            }
        }
        EditorGUILayout.EndHorizontal();
    }

    void DrawGrid()
    {
        int cols = Mathf.RoundToInt(roomSize.x);
        int rows = Mathf.RoundToInt(roomSize.y);
        int halfW = Mathf.FloorToInt(roomSize.x * 0.5f);
        int halfH = Mathf.FloorToInt(roomSize.y * 0.5f);

        float gridW = cols * cellSize;
        float gridH = rows * cellSize;

        scrollPos = EditorGUILayout.BeginScrollView(scrollPos,
            GUILayout.Height(Mathf.Min(gridH + 40, 500)),
            GUILayout.MaxWidth(gridW + 30));

        EditorGUILayout.BeginVertical(GUILayout.Width(gridW));

        for (int row = rows - 1; row >= 0; row--)
        {
            EditorGUILayout.BeginHorizontal(GUILayout.Width(gridW));
            for (int col = 0; col < cols; col++)
            {
                var cell = new Vector2Int(col - halfW, row - halfH);

                Color bg;
                string label = "";

                if (obstacleCellMap.TryGetValue(cell, out int obsIdx))
                {
                    if (obsIdx < 0)
                    {
                        bg = new Color(0.5f, 0.5f, 0.5f, 0.7f);
                        label = "×";
                    }
                    else
                    {
                        bg = ObstacleColors[obsIdx % ObstacleColors.Length];
                        label = obsIdx.ToString();
                    }
                }
                else if (enemySpawnCells.Contains(cell))
                {
                    bg = new Color(0.2f, 0.5f, 0.9f, 0.7f);
                    label = "E";
                }
                else if (itemSpawnCells.Contains(cell))
                {
                    bg = new Color(0.7f, 0.3f, 0.9f, 0.7f);
                    label = "I";
                }
                else
                    bg = new Color(0.6f, 0.6f, 0.6f, 0.3f);

                bool isHover = hoverCell.HasValue && hoverCell.Value == cell;
                if (isHover)
                    bg = Color.Lerp(bg, Color.yellow, 0.4f);

                var oldBg = GUI.backgroundColor;
                GUI.backgroundColor = bg;

                if (GUILayout.Button(label, GUILayout.Width(cellSize), GUILayout.Height(cellSize)))
                {
                    OnCellClicked(cell);
                    Repaint();
                }

                if (Event.current.type == EventType.Repaint)
                {
                    var btnRect = GUILayoutUtility.GetLastRect();
                    if (btnRect.Contains(Event.current.mousePosition))
                        hoverCell = cell;
                }

                GUI.backgroundColor = oldBg;
            }
            EditorGUILayout.EndHorizontal();
        }

        EditorGUILayout.EndVertical();
        EditorGUILayout.EndScrollView();
    }

    void DrawLegend(Color color, string label)
    {
        var rect = GUILayoutUtility.GetRect(12, 12, GUILayout.Width(12), GUILayout.Height(12));
        EditorGUI.DrawRect(rect, color);
        EditorGUILayout.LabelField(label, EditorStyles.miniLabel, GUILayout.Width(50));
    }

    // ──────────────────────────────────────────────
    //  交互
    // ──────────────────────────────────────────────

    void OnCellClicked(Vector2Int cell)
    {
        switch (editMode)
        {
            case EditMode.Obstacle:
                if (enemySpawnCells.Contains(cell)) return;
                if (itemSpawnCells.Contains(cell)) return;

                if (obstacleCellMap.TryGetValue(cell, out int existingIdx))
                {
                    if (existingIdx == selectedObstacleIndex)
                        // 同类型 → 删除
                        obstacleCellMap.Remove(cell);
                    else
                        // 不同类型(含-1原有障碍物) → 替换
                        obstacleCellMap[cell] = selectedObstacleIndex;
                }
                else
                    // 空格 → 放置
                    obstacleCellMap[cell] = selectedObstacleIndex;
                break;

            case EditMode.EnemySpawn:
                if (obstacleCellMap.ContainsKey(cell)) return;
                if (enemySpawnCells.Contains(cell))
                    enemySpawnCells.Remove(cell);
                else
                {
                    itemSpawnCells.Remove(cell);
                    enemySpawnCells.Add(cell);
                }
                break;

            case EditMode.ItemSpawn:
                if (obstacleCellMap.ContainsKey(cell)) return;
                if (itemSpawnCells.Contains(cell))
                    itemSpawnCells.Remove(cell);
                else
                {
                    enemySpawnCells.Remove(cell);
                    itemSpawnCells.Add(cell);
                }
                break;
        }
    }

    void ClearCurrentMode()
    {
        switch (editMode)
        {
            case EditMode.Obstacle: obstacleCellMap.Clear(); break;
            case EditMode.EnemySpawn: enemySpawnCells.Clear(); break;
            case EditMode.ItemSpawn: itemSpawnCells.Clear(); break;
        }
    }

    // ──────────────────────────────────────────────
    //  保存
    // ──────────────────────────────────────────────

    void SaveToPrefab()
    {
        if (roomPrefab == null) return;
        string path = AssetDatabase.GetAssetPath(roomPrefab);
        if (string.IsNullOrEmpty(path)) return;

        var root = PrefabUtility.LoadPrefabContents(path);
        var roomRoot = root.GetComponent<RoomRoot>();

        // ── 障碍物 ──
        // 先收集原有障碍物（idx=-1）的 GO，保留它们
        var oldObs = root.transform.Find("Obstacles");
        List<GameObject> preservedObstacles = new();
        if (oldObs != null)
        {
            for (int i = 0; i < oldObs.childCount; i++)
            {
                preservedObstacles.Add(oldObs.GetChild(i).gameObject);
            }
        }

        // 重新创建容器
        if (oldObs != null)
        {
            // 把原有子物体先移出，再删旧容器
            foreach (var go in preservedObstacles)
                go.transform.SetParent(root.transform, true);
            DestroyImmediate(oldObs.gameObject);
        }

        var obsContainer = new GameObject("Obstacles").transform;
        obsContainer.SetParent(root.transform, false);
        obsContainer.localPosition = Vector3.zero;

        int placedCount = 0;
        foreach (var kv in obstacleCellMap)
        {
            var cell = kv.Key;
            int idx = kv.Value;

            if (idx == -1)
            {
                // 原有障碍物 → 完全保留原始位置，不做任何修改
                var match = preservedObstacles.FirstOrDefault(go =>
                    WorldToCell(go.transform.localPosition) == cell);
                if (match != null)
                {
                    match.transform.SetParent(obsContainer, true);
                    preservedObstacles.Remove(match);
                    placedCount++;
                }
                continue;
            }

            if (idx < 0 || idx >= obstaclePrefabs.Count || obstaclePrefabs[idx] == null) continue;

            var go2 = (GameObject)PrefabUtility.InstantiatePrefab(obstaclePrefabs[idx], obsContainer);
            go2.name = $"Obstacle_{idx}_{placedCount}";
            go2.transform.localPosition = CellToWorld(cell);
            placedCount++;
        }

        // 销毁未被匹配的原有障碍物（用户在网格中删除的 ×）
        foreach (var leftover in preservedObstacles)
            DestroyImmediate(leftover);

        // ── 敌人生成点 ──
        var oldEnemy = root.transform.Find("EnemySpawnPoints");
        if (oldEnemy != null)
            DestroyImmediate(oldEnemy.gameObject);

        var enemyContainer = new GameObject("EnemySpawnPoints").transform;
        enemyContainer.SetParent(root.transform, false);
        enemyContainer.localPosition = Vector3.zero;

        var enemyArr = new Transform[enemySpawnCells.Count];
        int ei = 0;
        foreach (var cell in enemySpawnCells)
        {
            var go = new GameObject("E");
            go.transform.SetParent(enemyContainer, false);
            go.transform.localPosition = CellToWorldNoOffset(cell);
            enemyArr[ei++] = go.transform;
        }
        if (roomRoot != null)
            roomRoot.enemySpawnPoints = enemyArr;

        // ── 道具生成点 ──
        var oldItem = root.transform.Find("ItemSpawnPoints");
        if (oldItem != null)
            DestroyImmediate(oldItem.gameObject);

        var itemContainer = new GameObject("ItemSpawnPoints").transform;
        itemContainer.SetParent(root.transform, false);
        itemContainer.localPosition = Vector3.zero;

        var itemArr = new Transform[itemSpawnCells.Count];
        int ii = 0;
        foreach (var cell in itemSpawnCells)
        {
            var go = new GameObject("I");
            go.transform.SetParent(itemContainer, false);
            go.transform.localPosition = CellToWorldNoOffset(cell);
            itemArr[ii++] = go.transform;
        }
        if (roomRoot != null)
            roomRoot.itemSpawnPoints = itemArr;

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        needsRefresh = true;

        var typeCounts = obstacleCellMap.Values.Where(v => v >= 0).GroupBy(v => v).ToDictionary(g => g.Key, g => g.Count());
        int preservedCount = obstacleCellMap.Count(kv => kv.Value == -1);
        string typeInfo = string.Join("\n", typeCounts.Select(kv => $"  [{kv.Key}] {obstaclePrefabs[kv.Key]?.name}: {kv.Value}个"));
        if (preservedCount > 0)
            typeInfo += $"\n  [×] 原有保留: {preservedCount}个";

        Debug.Log($"[ObstacleGridEditor] 已保存: {placedCount}障碍物, {enemySpawnCells.Count}敌人点, {itemSpawnCells.Count}道具点 → {path}");
        EditorUtility.DisplayDialog("完成",
            $"已保存到:\n{path}\n\n" +
            $"障碍物: {placedCount}\n{typeInfo}\n\n" +
            $"敌人生成点: {enemySpawnCells.Count}\n" +
            $"道具生成点: {itemSpawnCells.Count}", "确定");
    }

    static void Warn(string msg) => EditorUtility.DisplayDialog("提示", msg, "确定");
}

using UnityEngine;
using UnityEditor;
using System.IO;
using System.Collections.Generic;
using System.Linq;

/// <summary>
/// 障碍物制造器 — 选择 Sprite，配置参数，一键生成障碍物预制体。
/// 菜单: Tools > 障碍物制造器
/// 单个生成，支持预案保存，配置持久化到 EditorPrefs。
/// </summary>
public class ObstacleMakerWindow : EditorWindow
{
    const string PresetsPrefsKey = "ObstacleMakerWindow_Presets";

    // === 障碍物类型 ===
    enum ObstacleType { Normal, HoleTrap, SpikeTrap }
    ObstacleType _obstacleType = ObstacleType.Normal;

    // === 洞陷阱参数 ===
    float _damageRatio = 0.1f;
    float _trapDuration = 2f;
    float _shrinkScale = 0.2f;
    float _popOffset = 1.5f;
    Vector2 _colliderSize = new Vector2(1f, 1f);

    // === 刺陷阱参数 ===
    Sprite _spikeSprite1;
    Sprite _spikeSprite2;
    Sprite _spikeSprite3;
    float _spikeDamageRatio = 0.1f;
    float _spikeDamageCooldown = 0.5f;
    float _spikeState1End = 1f;
    float _spikeState2FirstEnd = 1.5f;
    float _spikeState3End = 3f;
    float _spikeState2SecondEnd = 3.5f;

    // === 输入 Sprite (单个) ===
    Sprite sourceSprite;

    // === 预制体设置 ===
    Vector2 targetWorldSize = new(1f, 1f);

    // === 材质 ===
    Material spriteMaterial;

    // === 输出 ===
    string outputFolder = "Assets/Prefabs/Obstacles";
    string prefabName = "Obstacle";

    // === 预案系统 ===
    [System.Serializable]
    class ConfigData
    {
        public string sourceSpriteGUID;
        public Vector2 targetWorldSize = new(1f, 1f);
        public string materialGUID;
        public string outputFolder = "Assets/Prefabs/Obstacles";
        public string prefabName = "Obstacle";
        public int obstacleType = 0;
        public float damageRatio = 0.1f;
        public float trapDuration = 2f;
        public float shrinkScale = 0.2f;
        public float popOffset = 1.5f;
        public Vector2 colliderSize = new Vector2(1f, 1f);
        // Spike trap
        public string spikeSprite1GUID = "";
        public string spikeSprite2GUID = "";
        public string spikeSprite3GUID = "";
        public float spikeDamageRatio = 0.1f;
        public float spikeDamageCooldown = 0.5f;
        public float spikeState1End = 1f;
        public float spikeState2FirstEnd = 1.5f;
        public float spikeState3End = 3f;
        public float spikeState2SecondEnd = 3.5f;
    }

    [System.Serializable]
    class PresetData
    {
        public string name;
        public ConfigData config;
    }

    [System.Serializable]
    class PresetList
    {
        public List<PresetData> presets = new();
        public string currentName = "";
    }

    PresetList _presets;
    string _newPresetName = "";
    bool _renaming;
    string _renameBuffer = "";

    Vector2 _scroll;

    [MenuItem("Tools/障碍物制造器")]
    static void ShowWindow() => GetWindow<ObstacleMakerWindow>("障碍物制造器");

    void OnEnable()
    {
        LoadPresets();
    }

    void OnDestroy()
    {
        SaveCurrentToPresets();
        SavePresetsToDisk();
    }

    // ──────────────────────────────────────────────
    //  GUID 工具
    // ──────────────────────────────────────────────

    static string ToGUID(Object obj)
    {
        if (obj == null) return "";
        var path = AssetDatabase.GetAssetPath(obj);
        if (string.IsNullOrEmpty(path)) return "";
        return AssetDatabase.AssetPathToGUID(path);
    }

    static T FromGUID<T>(string guid) where T : Object
    {
        if (string.IsNullOrEmpty(guid)) return null;
        var path = AssetDatabase.GUIDToAssetPath(guid);
        if (string.IsNullOrEmpty(path)) return null;
        return AssetDatabase.LoadAssetAtPath<T>(path);
    }

    // ──────────────────────────────────────────────
    //  预案存取
    // ──────────────────────────────────────────────

    void LoadPresets()
    {
        var json = EditorPrefs.GetString(PresetsPrefsKey, "");
        if (!string.IsNullOrEmpty(json))
            _presets = JsonUtility.FromJson<PresetList>(json);

        if (_presets == null || _presets.presets.Count == 0)
        {
            _presets = new PresetList();
            _presets.presets.Add(new PresetData { name = "默认", config = new ConfigData() });
            _presets.currentName = "默认";
        }

        ApplyConfigToFields(GetCurrentPreset()?.config);
    }

    PresetData GetCurrentPreset()
    {
        if (_presets == null || _presets.presets.Count == 0) return null;
        return _presets.presets.FirstOrDefault(p => p.name == _presets.currentName)
               ?? _presets.presets[0];
    }

    void SaveCurrentToPresets()
    {
        var p = GetCurrentPreset();
        if (p != null) p.config = CollectFieldsToConfig();
    }

    void SavePresetsToDisk()
    {
        EditorPrefs.SetString(PresetsPrefsKey, JsonUtility.ToJson(_presets));
    }

    void ApplyConfigToFields(ConfigData d)
    {
        if (d == null)
        {
            spriteMaterial = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/SpriteLit.mat");
            return;
        }
        sourceSprite = FromGUID<Sprite>(d.sourceSpriteGUID);
        targetWorldSize = d.targetWorldSize;
        spriteMaterial = FromGUID<Material>(d.materialGUID);
        if (spriteMaterial == null)
            spriteMaterial = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/SpriteLit.mat");
        outputFolder = string.IsNullOrEmpty(d.outputFolder) ? "Assets/Prefabs/Obstacles" : d.outputFolder;
        prefabName = string.IsNullOrEmpty(d.prefabName) ? "Obstacle" : d.prefabName;
        _obstacleType = (ObstacleType)d.obstacleType;
        _damageRatio = d.damageRatio > 0f ? d.damageRatio : 0.1f;
        _trapDuration = d.trapDuration > 0f ? d.trapDuration : 2f;
        _shrinkScale = d.shrinkScale > 0f ? d.shrinkScale : 0.2f;
        _popOffset = d.popOffset > 0f ? d.popOffset : 1.5f;
        _colliderSize = d.colliderSize.magnitude > 0f ? d.colliderSize : new Vector2(1f, 1f);
        _spikeSprite1 = FromGUID<Sprite>(d.spikeSprite1GUID);
        _spikeSprite2 = FromGUID<Sprite>(d.spikeSprite2GUID);
        _spikeSprite3 = FromGUID<Sprite>(d.spikeSprite3GUID);
        _spikeDamageRatio = d.spikeDamageRatio > 0f ? d.spikeDamageRatio : 0.1f;
        _spikeDamageCooldown = d.spikeDamageCooldown > 0f ? d.spikeDamageCooldown : 0.5f;
        _spikeState1End = d.spikeState1End > 0f ? d.spikeState1End : 1f;
        _spikeState2FirstEnd = d.spikeState2FirstEnd > 0f ? d.spikeState2FirstEnd : 1.5f;
        _spikeState3End = d.spikeState3End > 0f ? d.spikeState3End : 3f;
        _spikeState2SecondEnd = d.spikeState2SecondEnd > 0f ? d.spikeState2SecondEnd : 3.5f;
    }

    ConfigData CollectFieldsToConfig()
    {
        return new ConfigData
        {
            sourceSpriteGUID = ToGUID(sourceSprite),
            targetWorldSize = targetWorldSize,
            materialGUID = ToGUID(spriteMaterial),
            outputFolder = outputFolder,
            prefabName = prefabName,
            obstacleType = (int)_obstacleType,
            damageRatio = _damageRatio,
            trapDuration = _trapDuration,
            shrinkScale = _shrinkScale,
            popOffset = _popOffset,
            colliderSize = _colliderSize,
            spikeSprite1GUID = ToGUID(_spikeSprite1),
            spikeSprite2GUID = ToGUID(_spikeSprite2),
            spikeSprite3GUID = ToGUID(_spikeSprite3),
            spikeDamageRatio = _spikeDamageRatio,
            spikeDamageCooldown = _spikeDamageCooldown,
            spikeState1End = _spikeState1End,
            spikeState2FirstEnd = _spikeState2FirstEnd,
            spikeState3End = _spikeState3End,
            spikeState2SecondEnd = _spikeState2SecondEnd
        };
    }

    // ──────────────────────────────────────────────
    //  UI
    // ──────────────────────────────────────────────

    void OnGUI()
    {
        _scroll = EditorGUILayout.BeginScrollView(_scroll);

        GUILayout.Label("障碍物制造器", EditorStyles.boldLabel);
        EditorGUILayout.HelpBox(
            "选择 Sprite → 配置参数 → 生成障碍物预制体。\n" +
            "不修改 TextureImporter，尊重已有 Sprite Editor 切片。\n" +
            "碰撞器与图案大小一致。\n" +
            "配置自动保存，关闭 Unity 不丢失。", MessageType.Info);

        DrawPresetSection();

        // ── 障碍物类型 ──
        EditorGUILayout.Space();
        GUILayout.Label("障碍物类型", EditorStyles.miniBoldLabel);
        _obstacleType = (ObstacleType)GUILayout.SelectionGrid(
            (int)_obstacleType, new[] { "普通障碍物", "洞陷阱", "刺陷阱" }, 3, GUILayout.Height(25));

        // ── 洞陷阱参数 ──
        if (_obstacleType == ObstacleType.HoleTrap)
        {
            EditorGUILayout.Space();
            GUILayout.Label("陷阱参数", EditorStyles.miniBoldLabel);
            _damageRatio = EditorGUILayout.Slider("扣血比例 (占最大生命)", _damageRatio, 0f, 1f);
            _trapDuration = EditorGUILayout.FloatField("陷入时间 (秒)", _trapDuration);
            _shrinkScale = EditorGUILayout.Slider("缩小倍率", _shrinkScale, 0.05f, 1f);
            _popOffset = EditorGUILayout.FloatField("弹出距离", _popOffset);
            _colliderSize = EditorGUILayout.Vector2Field("碰撞箱尺寸 (宽,高)", _colliderSize);
        }

        // ── 刺陷阱参数 ──
        if (_obstacleType == ObstacleType.SpikeTrap)
        {
            EditorGUILayout.Space();
            GUILayout.Label("刺陷阱参数", EditorStyles.miniBoldLabel);
            _spikeSprite1 = (Sprite)EditorGUILayout.ObjectField("状态1 Sprite (未探出)", _spikeSprite1, typeof(Sprite), false);
            _spikeSprite2 = (Sprite)EditorGUILayout.ObjectField("状态2 Sprite (将探出)", _spikeSprite2, typeof(Sprite), false);
            _spikeSprite3 = (Sprite)EditorGUILayout.ObjectField("状态3 Sprite (完全探出)", _spikeSprite3, typeof(Sprite), false);
            EditorGUILayout.Space();
            _spikeDamageRatio = EditorGUILayout.Slider("扣血比例 (占最大生命)", _spikeDamageRatio, 0f, 1f);
            _spikeDamageCooldown = EditorGUILayout.FloatField("伤害冷却 (秒)", _spikeDamageCooldown);
            EditorGUILayout.Space();
            GUILayout.Label("时序 (秒)", EditorStyles.miniBoldLabel);
            _spikeState1End = EditorGUILayout.FloatField("状态1结束", _spikeState1End);
            _spikeState2FirstEnd = EditorGUILayout.FloatField("状态2首段结束", _spikeState2FirstEnd);
            _spikeState3End = EditorGUILayout.FloatField("状态3结束", _spikeState3End);
            _spikeState2SecondEnd = EditorGUILayout.FloatField("状态2次段结束", _spikeState2SecondEnd);
        }

        // ── 输入 Sprite ──
        EditorGUILayout.Space();
        GUILayout.Label("输入 Sprite", EditorStyles.miniBoldLabel);

        // 拖放区域
        var dropArea = GUILayoutUtility.GetRect(0f, 50f, GUILayout.ExpandWidth(true));
        GUI.Box(dropArea, sourceSprite != null ? $"当前: {sourceSprite.name}" : "拖放 Sprite 到此处", GUI.skin.box);
        HandleDragDrop(dropArea);

        sourceSprite = (Sprite)EditorGUILayout.ObjectField("Sprite", sourceSprite, typeof(Sprite), false);

        // ── 障碍物尺寸 ──
        EditorGUILayout.Space();
        GUILayout.Label("障碍物尺寸", EditorStyles.miniBoldLabel);
        targetWorldSize = EditorGUILayout.Vector2Field("目标世界尺寸 (宽,高)", targetWorldSize);

        if (sourceSprite != null)
        {
            Vector2 natSize = sourceSprite.bounds.size;
            float scaleX = natSize.x > 0 ? targetWorldSize.x / natSize.x : 1f;
            float scaleY = natSize.y > 0 ? targetWorldSize.y / natSize.y : 1f;
            EditorGUILayout.LabelField("Sprite 原始世界尺寸", $"{natSize.x:F2} × {natSize.y:F2}", EditorStyles.miniLabel);
            EditorGUILayout.LabelField("缩放比例", $"X={scaleX:F3}  Y={scaleY:F3}", EditorStyles.miniLabel);

            // 预览缩略图
            var previewTex = AssetPreview.GetAssetPreview(sourceSprite);
            if (previewTex != null)
            {
                GUILayout.Space(5);
                GUILayout.Label(previewTex);
            }
        }

        // ── 材质 ──
        EditorGUILayout.Space();
        GUILayout.Label("材质", EditorStyles.miniBoldLabel);
        spriteMaterial = (Material)EditorGUILayout.ObjectField("材质", spriteMaterial, typeof(Material), false);
        if (spriteMaterial == null)
            EditorGUILayout.HelpBox("未指定材质，将使用 Sprites/Default", MessageType.Warning);

        // ── 输出 ──
        EditorGUILayout.Space();
        GUILayout.Label("输出", EditorStyles.miniBoldLabel);
        prefabName = EditorGUILayout.TextField("预制体名称", prefabName);

        EditorGUILayout.BeginHorizontal();
        EditorGUILayout.PrefixLabel("输出路径");
        outputFolder = EditorGUILayout.TextField(outputFolder);
        if (GUILayout.Button("浏览", GUILayout.Width(50)))
        {
            string absStart = Path.GetFullPath(outputFolder);
            if (!Directory.Exists(absStart)) absStart = Application.dataPath;
            string picked = EditorUtility.OpenFolderPanel("选择输出文件夹", absStart, "");
            if (!string.IsNullOrEmpty(picked))
            {
                string rel = FileUtil.GetProjectRelativePath(picked);
                if (!rel.StartsWith("Assets/")) { Warn("路径必须在 Assets/ 目录下"); }
                else outputFolder = rel.Replace('\\', '/');
            }
        }
        EditorGUILayout.EndHorizontal();
        EditorGUILayout.LabelField("完整路径", $"{outputFolder}/{prefabName}.prefab", EditorStyles.miniLabel);

        // ── 生成 ──
        EditorGUILayout.Space(10);
        using (new EditorGUI.DisabledScope(sourceSprite == null || spriteMaterial == null))
        {
            string btnLabel = _obstacleType switch
            {
                ObstacleType.HoleTrap => "生成洞陷阱预制体",
                ObstacleType.SpikeTrap => "生成刺陷阱预制体",
                _ => "生成障碍物预制体"
            };
            if (GUILayout.Button(btnLabel, GUILayout.Height(30)))
            {
                SaveCurrentToPresets();
                SavePresetsToDisk();
                switch (_obstacleType)
                {
                    case ObstacleType.HoleTrap: GenerateHoleTrap(); break;
                    case ObstacleType.SpikeTrap: GenerateSpikeTrap(); break;
                    default: GenerateObstacle(); break;
                }
            }
        }

        EditorGUILayout.EndScrollView();

        if (GUI.changed)
        {
            SaveCurrentToPresets();
            SavePresetsToDisk();
        }
    }

    void DrawPresetSection()
    {
        EditorGUILayout.Space();
        GUILayout.Label("预案", EditorStyles.miniBoldLabel);

        if (_renaming)
        {
            EditorGUILayout.BeginHorizontal();
            _renameBuffer = EditorGUILayout.TextField("编辑预案名", _renameBuffer);
            if (GUILayout.Button("确定", GUILayout.Width(40)))
            {
                var p = GetCurrentPreset();
                if (p != null && !string.IsNullOrWhiteSpace(_renameBuffer))
                {
                    _presets.currentName = _renameBuffer;
                    p.name = _renameBuffer;
                    SavePresetsToDisk();
                }
                _renaming = false;
            }
            if (GUILayout.Button("取消", GUILayout.Width(40)))
                _renaming = false;
            EditorGUILayout.EndHorizontal();
        }

        string[] names = _presets.presets.Select(p => p.name).ToArray();
        int curIdx = System.Array.IndexOf(names, _presets.currentName);
        if (curIdx < 0) curIdx = 0;

        EditorGUILayout.BeginHorizontal();
        int newIdx = EditorGUILayout.Popup("当前预案", curIdx, names);
        if (newIdx != curIdx)
        {
            SaveCurrentToPresets();
            _presets.currentName = names[newIdx];
            ApplyConfigToFields(GetCurrentPreset()?.config);
            SavePresetsToDisk();
        }

        if (GUILayout.Button("重命名", GUILayout.Width(60)))
        {
            var p = GetCurrentPreset();
            if (p != null)
            {
                _renameBuffer = p.name;
                _renaming = true;
            }
        }

        if (GUILayout.Button("删除", GUILayout.Width(50)))
        {
            if (_presets.presets.Count <= 1)
                Warn("至少保留一个预案");
            else
            {
                var p = GetCurrentPreset();
                if (p != null)
                {
                    _presets.presets.Remove(p);
                    _presets.currentName = _presets.presets[0].name;
                    ApplyConfigToFields(GetCurrentPreset()?.config);
                    SavePresetsToDisk();
                }
            }
        }
        EditorGUILayout.EndHorizontal();

        EditorGUILayout.BeginHorizontal();
        _newPresetName = EditorGUILayout.TextField("新预案名称", _newPresetName);
        if (GUILayout.Button("新建", GUILayout.Width(50)))
        {
            if (string.IsNullOrWhiteSpace(_newPresetName))
                Warn("请输入预案名称");
            else if (_presets.presets.Any(p => p.name == _newPresetName))
                Warn("预案名称已存在");
            else
            {
                SaveCurrentToPresets();
                _presets.presets.Add(new PresetData
                {
                    name = _newPresetName,
                    config = CollectFieldsToConfig()
                });
                _presets.currentName = _newPresetName;
                _newPresetName = "";
                SavePresetsToDisk();
            }
        }
        EditorGUILayout.EndHorizontal();
    }

    // ──────────────────────────────────────────────
    //  拖放
    // ──────────────────────────────────────────────

    void HandleDragDrop(Rect dropArea)
    {
        var evt = Event.current;
        if (evt.type == EventType.DragUpdated && dropArea.Contains(evt.mousePosition))
        {
            bool hasSprite = DragAndDrop.objectReferences.OfType<Sprite>().Any();
            DragAndDrop.visualMode = hasSprite ? DragAndDropVisualMode.Copy : DragAndDropVisualMode.Rejected;
            Event.current.Use();
        }
        else if (evt.type == EventType.DragPerform && dropArea.Contains(evt.mousePosition))
        {
            DragAndDrop.AcceptDrag();
            var sp = DragAndDrop.objectReferences.OfType<Sprite>().FirstOrDefault();
            if (sp != null)
                sourceSprite = sp;
            Event.current.Use();
        }
    }

    // ──────────────────────────────────────────────
    //  生成
    // ──────────────────────────────────────────────

    void GenerateObstacle()
    {
        if (sourceSprite == null) { Warn("请选择 Sprite"); return; }
        if (spriteMaterial == null) { Warn("请指定材质"); return; }

        if (!AssetDatabase.IsValidFolder(outputFolder))
        {
            string parent = Path.GetDirectoryName(outputFolder).Replace('\\', '/');
            string folderName = Path.GetFileName(outputFolder);
            if (!AssetDatabase.IsValidFolder(parent))
            {
                Warn($"父文件夹不存在: {parent}");
                return;
            }
            AssetDatabase.CreateFolder(parent, folderName);
        }

        EnsureTag("Obstacles");

        string prefabPath = $"{outputFolder}/{prefabName}.prefab";

        var go = new GameObject(prefabName);
        go.tag = "Obstacles";

        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = sourceSprite;
        sr.sharedMaterial = spriteMaterial;
        sr.sortingOrder = 0;
        sr.drawMode = SpriteDrawMode.Simple;

        // 缩放到目标世界尺寸
        Vector2 spriteWorldSize = sourceSprite.bounds.size;
        float sx = spriteWorldSize.x > 0 ? targetWorldSize.x / spriteWorldSize.x : 1f;
        float sy = spriteWorldSize.y > 0 ? targetWorldSize.y / spriteWorldSize.y : 1f;
        go.transform.localScale = new Vector3(sx, sy, 1f);

        var col = go.AddComponent<BoxCollider2D>();
        col.size = spriteWorldSize;  // 局部空间=Sprite原始尺寸, 缩放后自动匹配图案

        PrefabUtility.SaveAsPrefabAsset(go, prefabPath);
        DestroyImmediate(go);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log($"[ObstacleMaker] 生成: {prefabPath} | Sprite: {sourceSprite.name} | 原始: {spriteWorldSize} → 目标: {targetWorldSize}");
        EditorUtility.DisplayDialog("完成", $"障碍物预制体已生成:\n{prefabPath}", "确定");
    }

    void GenerateHoleTrap()
    {
        if (sourceSprite == null) { Warn("请选择 Sprite"); return; }
        if (spriteMaterial == null) { Warn("请指定材质"); return; }

        if (!AssetDatabase.IsValidFolder(outputFolder))
        {
            string parent = Path.GetDirectoryName(outputFolder).Replace('\\', '/');
            string folderName = Path.GetFileName(outputFolder);
            if (!AssetDatabase.IsValidFolder(parent))
            {
                Warn($"父文件夹不存在: {parent}");
                return;
            }
            AssetDatabase.CreateFolder(parent, folderName);
        }

        EnsureTag("Hole");

        string prefabPath = $"{outputFolder}/{prefabName}.prefab";

        var go = new GameObject(prefabName);
        go.tag = "Hole";

        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = sourceSprite;
        sr.sharedMaterial = spriteMaterial;
        sr.sortingOrder = 0;
        sr.drawMode = SpriteDrawMode.Simple;

        // 缩放到目标世界尺寸
        Vector2 spriteWorldSize = sourceSprite.bounds.size;
        float sx = spriteWorldSize.x > 0 ? targetWorldSize.x / spriteWorldSize.x : 1f;
        float sy = spriteWorldSize.y > 0 ? targetWorldSize.y / spriteWorldSize.y : 1f;
        go.transform.localScale = new Vector3(sx, sy, 1f);

        // 碰撞器：isTrigger + 指定尺寸
        var col = go.AddComponent<BoxCollider2D>();
        col.size = _colliderSize;
        col.isTrigger = true;

        // 添加 HoleTrap 组件并配置参数
        var trap = go.AddComponent<HoleTrap>();
        trap.Configure(_damageRatio, _trapDuration, _shrinkScale, _popOffset);

        PrefabUtility.SaveAsPrefabAsset(go, prefabPath);
        DestroyImmediate(go);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log($"[ObstacleMaker] 生成洞陷阱: {prefabPath} | Sprite: {sourceSprite.name} | 碰撞箱尺寸: {_colliderSize} | 扣血: {_damageRatio} | 陷入: {_trapDuration}s | 缩小: {_shrinkScale}");
        EditorUtility.DisplayDialog("完成", $"洞陷阱预制体已生成:\n{prefabPath}", "确定");
    }

    void GenerateSpikeTrap()
    {
        if (_spikeSprite1 == null || _spikeSprite2 == null || _spikeSprite3 == null)
        { Warn("请指定三张状态 Sprite"); return; }
        if (spriteMaterial == null) { Warn("请指定材质"); return; }

        if (!AssetDatabase.IsValidFolder(outputFolder))
        {
            string parent = Path.GetDirectoryName(outputFolder).Replace('\\', '/');
            string folderName = Path.GetFileName(outputFolder);
            if (!AssetDatabase.IsValidFolder(parent))
            { Warn($"父文件夹不存在: {parent}"); return; }
            AssetDatabase.CreateFolder(parent, folderName);
        }

        EnsureTag("Spike");

        string prefabPath = $"{outputFolder}/{prefabName}.prefab";

        var go = new GameObject(prefabName);
        go.tag = "Spike";

        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = _spikeSprite1;
        sr.sharedMaterial = spriteMaterial;
        sr.sortingOrder = 0;

        // 缩放到目标世界尺寸
        Vector2 spriteWorldSize = _spikeSprite1.bounds.size;
        float sx = spriteWorldSize.x > 0 ? targetWorldSize.x / spriteWorldSize.x : 1f;
        float sy = spriteWorldSize.y > 0 ? targetWorldSize.y / spriteWorldSize.y : 1f;
        go.transform.localScale = new Vector3(sx, sy, 1f);

        var col = go.AddComponent<BoxCollider2D>();
        col.size = spriteWorldSize;
        col.isTrigger = true;

        var spike = go.AddComponent<NerveSpike>();
        var so = new SerializedObject(spike);
        so.FindProperty("_state1Sprite").objectReferenceValue = _spikeSprite1;
        so.FindProperty("_state2Sprite").objectReferenceValue = _spikeSprite2;
        so.FindProperty("_state3Sprite").objectReferenceValue = _spikeSprite3;
        so.FindProperty("_state1End").floatValue = _spikeState1End;
        so.FindProperty("_state2FirstEnd").floatValue = _spikeState2FirstEnd;
        so.FindProperty("_state3End").floatValue = _spikeState3End;
        so.FindProperty("_state2SecondEnd").floatValue = _spikeState2SecondEnd;
        so.FindProperty("_damageRatio").floatValue = _spikeDamageRatio;
        so.FindProperty("_damageCooldown").floatValue = _spikeDamageCooldown;
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(go, prefabPath);
        DestroyImmediate(go);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log($"[ObstacleMaker] 生成刺陷阱: {prefabPath} | spriteSize={spriteWorldSize} | 扣血: {_spikeDamageRatio*100}% | 时序: {_spikeState1End}/{_spikeState2FirstEnd}/{_spikeState3End}/{_spikeState2SecondEnd}");
        EditorUtility.DisplayDialog("完成", $"刺陷阱预制体已生成:\n{prefabPath}", "确定");
    }

    // ──────────────────────────────────────────────
    //  工具
    // ──────────────────────────────────────────────

    static void EnsureTag(string tag)
    {
        var tags = UnityEditorInternal.InternalEditorUtility.tags;
        if (!tags.Contains(tag))
            UnityEditorInternal.InternalEditorUtility.AddTag(tag);
    }

    static void Warn(string msg) => EditorUtility.DisplayDialog("提示", msg, "确定");
}

using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.Linq;

/// <summary>
/// 障碍物 Scene 编辑工具 — 在 Scene View 中点击格子放置/删除障碍物。
/// 菜单: Tools > 障碍物 Scene 编辑
/// 左键放置，右键删除，保证格子正中心对齐。
/// </summary>
public class ObstacleSceneTool : EditorWindow
{
    static bool enabled = false;

    GameObject roomPrefab;
    List<GameObject> obstaclePrefabs = new();
    int selectedObstacleIndex = 0;

    // 运行时缓存（避免每帧 LoadPrefabContents）
    GameObject _cachedRoot;
    string _cachedPath;
    Vector2 _roomSize = new(20, 12);
    float _cellOffsetX = 0.5f;   // 偶数=0.5, 奇数=0
    float _cellOffsetY = 0.5f;
    HashSet<Vector2Int> _forbiddenCells = new();

    [MenuItem("Tools/障碍物 Scene 编辑")]
    static void ShowWindow()
    {
        var wnd = GetWindow<ObstacleSceneTool>("障碍物 Scene 编辑");
        enabled = true;
        SceneView.duringSceneGui += wnd.OnSceneGUI;
    }

    void OnEnable()
    {
        // 默认加载障碍物预制体
        string[] guids = AssetDatabase.FindAssets("t:Prefab", new[] { "Assets/Prefabs/Obstacles" });
        foreach (var g in guids)
        {
            var path = AssetDatabase.GUIDToAssetPath(g);
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (prefab != null) obstaclePrefabs.Add(prefab);
        }
    }

    void OnDestroy()
    {
        Disable();
    }

    void Disable()
    {
        enabled = false;
        SceneView.duringSceneGui -= OnSceneGUI;
        // 清理缓存
        if (_cachedRoot != null && !string.IsNullOrEmpty(_cachedPath))
        {
            PrefabUtility.UnloadPrefabContents(_cachedRoot);
            _cachedRoot = null;
        }
        SceneView.RepaintAll();
    }

    // ──────────────────────────────────────────────
    //  UI
    // ──────────────────────────────────────────────

    void OnGUI()
    {
        GUILayout.Label("障碍物 Scene 编辑", EditorStyles.boldLabel);
        EditorGUILayout.HelpBox(
            "1. 选择目标房间预制体\n" +
            "2. 点击「开启 Scene 编辑」\n" +
            "3. 在 Scene View 中:\n" +
            "   左键点击空格 → 放置障碍物\n" +
            "   左键点击已有障碍物 → 删除\n" +
            "   右键 → 删除障碍物\n" +
            "4. 点击「保存到预制体」保存修改\n" +
            "所有障碍物自动对齐到格子正中心。",
            MessageType.Info);

        EditorGUILayout.Space(5);
        roomPrefab = (GameObject)EditorGUILayout.ObjectField("房间预制体", roomPrefab, typeof(GameObject), false);

        // 障碍物预制体列表
        EditorGUILayout.LabelField("障碍物预制体:");
        for (int i = obstaclePrefabs.Count - 1; i >= 0; i--)
        {
            EditorGUILayout.BeginHorizontal();
            obstaclePrefabs[i] = (GameObject)EditorGUILayout.ObjectField(obstaclePrefabs[i], typeof(GameObject), false);
            if (GUILayout.Button("删", GUILayout.Width(30)))
            {
                obstaclePrefabs.RemoveAt(i);
                if (selectedObstacleIndex >= obstaclePrefabs.Count)
                    selectedObstacleIndex = Mathf.Max(0, obstaclePrefabs.Count - 1);
            }
            EditorGUILayout.EndHorizontal();
        }
        if (GUILayout.Button("+ 添加障碍物预制体"))
            obstaclePrefabs.Add(null);

        if (obstaclePrefabs.Count > 0 && obstaclePrefabs.All(p => p != null))
        {
            string[] names = obstaclePrefabs.Select(p => p.name).ToArray();
            selectedObstacleIndex = EditorGUILayout.Popup("当前障碍物", selectedObstacleIndex, names);
        }

        EditorGUILayout.Space(10);

        EditorGUILayout.BeginHorizontal();
        if (!enabled)
        {
            if (GUILayout.Button("开启 Scene 编辑", GUILayout.Height(30)))
            {
                if (roomPrefab == null) { EditorUtility.DisplayDialog("提示", "请选择房间预制体", "确定"); return; }
                if (obstaclePrefabs.Count == 0 || obstaclePrefabs.Any(p => p == null))
                { EditorUtility.DisplayDialog("提示", "请添加障碍物预制体", "确定"); return; }

                enabled = true;
                SceneView.duringSceneGui += OnSceneGUI;
                CacheRoomData();
                SceneView.RepaintAll();
            }
        }
        else
        {
            if (GUILayout.Button("关闭 Scene 编辑", GUILayout.Height(30)))
                Disable();
        }

        if (GUILayout.Button("保存到预制体", GUILayout.Height(30)))
            SaveToPrefab();

        if (GUILayout.Button("刷新缓存", GUILayout.Height(30), GUILayout.Width(80)))
            CacheRoomData();
        EditorGUILayout.EndHorizontal();

        if (enabled && _cachedRoot != null)
        {
            EditorGUILayout.Space(5);
            EditorGUILayout.LabelField($"房间: {_cachedPath}", EditorStyles.miniLabel);
            EditorGUILayout.LabelField($"房间尺寸: {_roomSize.x}×{_roomSize.y}", EditorStyles.miniLabel);

            // 统计当前障碍物数量
            var container = _cachedRoot.transform.Find("Obstacles");
            int count = container != null ? container.childCount : 0;
            EditorGUILayout.LabelField($"障碍物数量: {count}", EditorStyles.miniLabel);
        }
    }

    // ──────────────────────────────────────────────
    //  缓存房间数据
    // ──────────────────────────────────────────────

    void CacheRoomData()
    {
        if (roomPrefab == null) return;
        string path = AssetDatabase.GetAssetPath(roomPrefab);
        if (string.IsNullOrEmpty(path)) return;

        // 清理旧缓存
        if (_cachedRoot != null && !string.IsNullOrEmpty(_cachedPath))
            PrefabUtility.UnloadPrefabContents(_cachedRoot);

        _cachedPath = path;
        _cachedRoot = PrefabUtility.LoadPrefabContents(path);
        _forbiddenCells.Clear();

        var roomRoot = _cachedRoot.GetComponent<RoomRoot>();
        if (roomRoot != null)
        {
            _roomSize = roomRoot.roomSize;
            _cellOffsetX = (Mathf.RoundToInt(_roomSize.x) % 2 == 0) ? 0.5f : 0f;
            _cellOffsetY = (Mathf.RoundToInt(_roomSize.y) % 2 == 0) ? 0.5f : 0f;
            if (roomRoot.topDoor) _forbiddenCells.Add(WorldToCell(roomRoot.topDoor.localPosition));
            if (roomRoot.bottomDoor) _forbiddenCells.Add(WorldToCell(roomRoot.bottomDoor.localPosition));
            if (roomRoot.leftDoor) _forbiddenCells.Add(WorldToCell(roomRoot.leftDoor.localPosition));
            if (roomRoot.rightDoor) _forbiddenCells.Add(WorldToCell(roomRoot.rightDoor.localPosition));
            if (roomRoot.enemySpawnPoints != null)
                foreach (var t in roomRoot.enemySpawnPoints)
                    if (t) _forbiddenCells.Add(WorldToCell(t.localPosition));
            if (roomRoot.itemSpawnPoints != null)
                foreach (var t in roomRoot.itemSpawnPoints)
                    if (t) _forbiddenCells.Add(WorldToCell(t.localPosition));
        }

        SceneView.RepaintAll();
    }

    // ──────────────────────────────────────────────
    //  坐标转换
    // ──────────────────────────────────────────────

    Vector2Int WorldToCell(Vector3 worldPos)
    {
        return new Vector2Int(
            Mathf.RoundToInt(worldPos.x - _cellOffsetX),
            Mathf.RoundToInt(worldPos.y - _cellOffsetY));
    }

    Vector3 CellToWorld(Vector2Int cell)
    {
        return new Vector3(cell.x + _cellOffsetX, cell.y + _cellOffsetY, 0);
    }

    // ──────────────────────────────────────────────
    //  Scene GUI
    // ──────────────────────────────────────────────

    void OnSceneGUI(SceneView sceneView)
    {
        if (!enabled || _cachedRoot == null) return;

        Event e = Event.current;

        // 绘制网格
        DrawGrid(sceneView);

        // 绘制禁放格子
        foreach (var cell in _forbiddenCells)
        {
            Vector3 center = CellToWorld(cell);
            Handles.color = new Color(0.8f, 0.2f, 0.2f, 0.4f);
            Handles.DrawSolidRectangleWithOutline(
                new Rect(center.x - 0.5f, center.y - 0.5f, 1f, 1f),
                new Color(0.8f, 0.2f, 0.2f, 0.2f),
                new Color(0.8f, 0.2f, 0.2f, 0.6f));
        }

        // 标记已有障碍物
        var container = _cachedRoot.transform.Find("Obstacles");
        if (container != null)
        {
            for (int i = 0; i < container.childCount; i++)
            {
                var child = container.GetChild(i);
                Vector3 center = child.localPosition;
                Handles.color = new Color(0.2f, 0.8f, 0.2f, 0.5f);
                Handles.DrawWireCube(center, new Vector3(0.9f, 0.9f, 0));
            }
        }

        // 鼠标悬停高亮
        Vector2Int? hoverCell = GetMouseCell(e, sceneView);
        if (hoverCell.HasValue)
        {
            Vector3 center = CellToWorld(hoverCell.Value);
            Handles.color = Color.yellow;
            Handles.DrawWireCube(center, new Vector3(1f, 1f, 0));

            // 显示坐标
            Handles.Label(center + Vector3.up * 0.6f, $"({hoverCell.Value.x}, {hoverCell.Value.y})");
        }

        // 处理点击
        if (e.type == EventType.MouseDown && !e.alt)
        {
            if (hoverCell.HasValue)
            {
                if (e.button == 0) // 左键
                {
                    ToggleObstacle(hoverCell.Value);
                    e.Use();
                }
                else if (e.button == 1) // 右键
                {
                    RemoveObstacle(hoverCell.Value);
                    e.Use();
                }
            }
        }
    }

    void DrawGrid(SceneView sceneView)
    {
        int cols = Mathf.RoundToInt(_roomSize.x);
        int rows = Mathf.RoundToInt(_roomSize.y);
        int halfW = Mathf.FloorToInt(_roomSize.x * 0.5f);
        int halfH = Mathf.FloorToInt(_roomSize.y * 0.5f);

        // 格子中心偏移：偶数=n+0.5（边界在整数），奇数=n（边界在 n±0.5）
        float gridOffsetX = _cellOffsetX - 0.5f;  // 偶数=0, 奇数=-0.5
        float gridOffsetY = _cellOffsetY - 0.5f;

        float startX = -halfW + gridOffsetX;
        float endX = startX + cols;
        float startY = -halfH + gridOffsetY;
        float endY = startY + rows;

        Handles.color = new Color(1f, 1f, 1f, 0.2f);

        // 垂直线
        for (int i = 0; i <= cols; i++)
        {
            float x = startX + i;
            Handles.DrawLine(new Vector3(x, startY, 0), new Vector3(x, endY, 0));
        }

        // 水平线
        for (int i = 0; i <= rows; i++)
        {
            float y = startY + i;
            Handles.DrawLine(new Vector3(startX, y, 0), new Vector3(endX, y, 0));
        }

        // 房间边界
        Handles.color = new Color(1f, 1f, 1f, 0.5f);
        Handles.DrawLine(new Vector3(startX, startY, 0), new Vector3(endX, startY, 0));
        Handles.DrawLine(new Vector3(startX, endY, 0), new Vector3(endX, endY, 0));
        Handles.DrawLine(new Vector3(startX, startY, 0), new Vector3(startX, endY, 0));
        Handles.DrawLine(new Vector3(endX, startY, 0), new Vector3(endX, endY, 0));
    }

    Vector2Int? GetMouseCell(Event e, SceneView sceneView)
    {
        if (e == null) return null;

        Ray ray = HandleUtility.GUIPointToWorldRay(e.mousePosition);
        // 投影到 z=0 平面
        float t = -ray.origin.z / ray.direction.z;
        if (t < 0) return null;
        Vector3 worldPos = ray.origin + ray.direction * t;

        return WorldToCell(worldPos);
    }

    // ──────────────────────────────────────────────
    //  障碍物操作
    // ──────────────────────────────────────────────

    void ToggleObstacle(Vector2Int cell)
    {
        if (_forbiddenCells.Contains(cell)) return;

        var container = _cachedRoot.transform.Find("Obstacles");
        if (container == null)
        {
            var go = new GameObject("Obstacles");
            go.transform.SetParent(_cachedRoot.transform, false);
            go.transform.localPosition = Vector3.zero;
            container = go.transform;
        }

        // 检查是否已有障碍物
        Vector3 worldPos = CellToWorld(cell);
        for (int i = 0; i < container.childCount; i++)
        {
            var child = container.GetChild(i);
            if (Vector3.Distance(child.localPosition, worldPos) < 0.1f)
            {
                // 已有 → 删除
                Undo.DestroyObjectImmediate(child.gameObject);
                SceneView.RepaintAll();
                return;
            }
        }

        // 放置新障碍物
        var prefab = obstaclePrefabs[selectedObstacleIndex % obstaclePrefabs.Count];
        var obstacle = (GameObject)PrefabUtility.InstantiatePrefab(prefab, container);
        obstacle.name = $"Obstacle";
        obstacle.transform.localPosition = worldPos;
        Undo.RegisterCreatedObjectUndo(obstacle, "Place Obstacle");
        SceneView.RepaintAll();
    }

    void RemoveObstacle(Vector2Int cell)
    {
        var container = _cachedRoot.transform.Find("Obstacles");
        if (container == null) return;

        Vector3 worldPos = CellToWorld(cell);
        for (int i = 0; i < container.childCount; i++)
        {
            var child = container.GetChild(i);
            if (Vector3.Distance(child.localPosition, worldPos) < 0.1f)
            {
                Undo.DestroyObjectImmediate(child.gameObject);
                SceneView.RepaintAll();
                return;
            }
        }
    }

    // ──────────────────────────────────────────────
    //  保存
    // ──────────────────────────────────────────────

    void SaveToPrefab()
    {
        if (_cachedRoot == null || string.IsNullOrEmpty(_cachedPath)) return;

        // 重命名障碍物（按序号）
        var container = _cachedRoot.transform.Find("Obstacles");
        if (container != null)
        {
            int i = 0;
            for (int c = 0; c < container.childCount; c++)
                container.GetChild(c).name = $"Obstacle_{i++}";
        }

        PrefabUtility.SaveAsPrefabAsset(_cachedRoot, _cachedPath);
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        ShowNotification(new GUIContent($"已保存到 {_cachedPath}"));
        Debug.Log($"[ObstacleSceneTool] 已保存到 {_cachedPath}");
    }
}

using UnityEngine;
using UnityEditor;
using System.IO;
using System.Collections.Generic;
using System.Linq;

/// <summary>
/// 房间搭建工具 — 自动平铺地板/墙壁/门，生成房间预制体。
/// 菜单: Tools > 搭建房间
/// 支持多预案保存，配置持久化到 EditorPrefs。
/// </summary>
public class RoomBuilderTool : EditorWindow
{
    const string PresetsPrefsKey = "RoomBuilderTool_Presets";
    const string OldPrefsKey = "RoomBuilderTool_Config";

    // === 格子与房间 ===
    float tileSize = 1f;
    int roomTilesX = 20;
    int roomTilesY = 12;

    // === 地板 ===
    enum FloorMode { Tiled, Single }
    FloorMode floorMode = FloorMode.Single;
    Sprite floorSprite;
    Vector2 floorScale = new(1f, 1f), floorOffset = Vector2.zero;

    // === 墙壁 ===
    Sprite wallTopSprite, wallBottomSprite, wallLeftSprite, wallRightSprite;
